-- 由 deploy/tools/gen-farm-seed.py 生成，不要手改；改 mock-server/seed 后重新生成
BEGIN;
DELETE FROM system_user_role;
DELETE FROM system_role_menu;
DELETE FROM system_users;
DELETE FROM system_role;
DELETE FROM system_dept;
DELETE FROM system_tenant_package;
DELETE FROM system_tenant;
DELETE FROM system_menu WHERE type <> 3;
DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM system_menu WHERE type = 3 AND id < 100000 AND permission !~ '^(system:(user|role|dept|dict|tenant|tenant-package|permission)|system:menu:query)');
DELETE FROM system_menu WHERE type = 3 AND id < 100000 AND permission !~ '^(system:(user|role|dept|dict|tenant|tenant-package|permission)|system:menu:query)';
UPDATE system_menu SET parent_id = CASE
  WHEN permission ~ '^system:user' THEN 100201
  WHEN permission ~ '^system:(role|permission|menu)' THEN 100202
  WHEN permission ~ '^system:dict' THEN 100203
  WHEN permission ~ '^system:dept' THEN 100208
  WHEN permission ~ '^system:tenant-package' THEN 100103
  ELSE 100102 END
WHERE type = 3 AND id < 100000;
SELECT setval('farm_base_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM farm_base) + 1, 1000), false);
